<template>
  <div class="welfare-admin">
    <header><div><p class="eyebrow">营销增长 / 校园福利</p><h2>福利抽奖</h2><p>把小惊喜送到校园。即刻抽奖与报名开奖，统一管理。</p></div><div class="actions"><el-button v-if="canEdit" @click="redeemOpen = true">实物奖品核销</el-button><el-button v-if="canEdit" type="primary" @click="create">＋ 创建抽奖活动</el-button></div></header>
    <div class="mode-intro"><div><b>01 · 即刻抽奖</b><p>刮开揭晓，按每日次数与奖品概率参与</p></div><div><b>02 · 报名开奖</b><p>报名、等待、统一开奖，自动保存结果</p></div><div><b>奖品与领取</b><p>优惠券自动入账 · 实物凭码自提</p></div></div>
    <div class="panel filters"><el-input v-model="keyword" clearable placeholder="搜索活动名称" @keyup.enter="search"/><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="(label, key) in statuses" :key="key" :value="key" :label="label"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="load">刷新</el-button></div>
    <div v-if="error" class="error">{{ error }}</div>
    <div class="panel"><el-table v-loading="loading" :data="rows" empty-text="还没有抽奖活动，创建你的第一场校园福利">
      <el-table-column label="活动" min-width="250"><template #default="{row}"><div class="activity-cell"><img v-if="row.cover" :src="row.cover"/><div v-else class="cover-mark">礼</div><div><b>{{row.title}}</b><p>{{row.mode === 'instant' ? '即刻抽奖' : '报名开奖'}} · {{statuses[row.status]}}</p></div></div></template></el-table-column>
      <el-table-column label="参与 / 上限" width="140"><template #default="{row}">{{row.entryCount}} / {{row.maxEntries}}</template></el-table-column>
      <el-table-column label="随机奖品 / 赠送" width="150"><template #default="{row}">{{row.prizes.reduce((n:number,p:any)=>n+p.quantity,0)}} / {{row._count?.gifts || 0}}</template></el-table-column>
      <el-table-column label="开奖 / 结束时间" min-width="190"><template #default="{row}">{{time(row.drawAt || row.endAt)}}<p v-if="row.lastError" class="error">处理异常，打开详情查看</p></template></el-table-column>
      <el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row.id,'config')">{{row.status==='draft'&&canEdit?'编辑':'详情'}}</el-button><el-button link type="primary" @click="open(row.id,'entries')">参与记录</el-button></template></el-table-column>
    </el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load"/></div>

    <el-drawer v-model="drawer" :title="form.id ? form.title : '创建福利抽奖'" size="min(1060px, 95vw)" :close-on-click-modal="false">
      <div v-loading="detailLoading">
        <el-alert v-if="form.publishedAt" title="活动已发布，规则已锁定。暂停只停止新增参与，定时活动仍按原时间开奖。" type="info" :closable="false"/>
        <el-alert v-if="form.lastError" :title="form.lastError" type="error" :closable="false"/>
        <el-alert v-if="form.pendingAwards" :title="`${form.pendingAwards} 份奖品券等待发放；请检查券状态和有效期，后台会自动重试。`" type="warning" :closable="false"/>
        <el-tabs v-model="tab" @tab-change="tabChanged">
          <el-tab-pane label="活动与奖品" name="config">
            <el-alert v-if="editable && hasSavedGifts" title="已配置赠送名单，活动和奖品暂不可改；如需修改，请由超级管理员先清空并保存名单。" type="info" :closable="false"/><el-form label-position="top" :disabled="!editable || !!hasSavedGifts" class="campaign-form">
              <el-form-item label="抽奖模式"><el-radio-group v-model="form.mode"><el-radio-button value="instant">即刻抽奖 · 刮刮卡</el-radio-button><el-radio-button value="scheduled">报名后 · 定时开奖</el-radio-button></el-radio-group></el-form-item>
              <div class="grid"><el-form-item label="活动标题"><el-input v-model="form.title" maxlength="80" show-word-limit/></el-form-item><el-form-item label="活动校区"><el-select v-model="form.regionId" :empty-values="[null, undefined]" filterable placeholder="请选择校区"><el-option v-if="options.canGlobal" label="全部校区" value=""/><el-option v-for="r in options.regions" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item></div>
              <el-form-item label="活动封面（留空使用默认小兔主题）"><ImageUploadBox v-if="editable" v-model="form.cover" shape="wide" scene="activity" :max-size="2" tip="建议宽图 1200 × 600，重点内容放在右侧"/><img v-else-if="form.cover" class="cover-preview" :src="form.cover"/><span v-else>默认小兔主题</span></el-form-item>
              <div class="grid"><el-form-item label="开始时间"><el-date-picker v-model="form.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item :label="form.mode==='instant'?'抽奖结束':'报名截止'"><el-date-picker v-model="form.endAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item v-if="form.mode==='scheduled'" label="统一开奖时间"><el-date-picker v-model="form.drawAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="领奖截止时间"><el-date-picker v-model="form.claimUntil" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item></div>
              <p class="hint">所有时间按当前电脑时区显示（{{timezone}}）。报名截止 ≤ 开奖时间 &lt; 领奖截止。</p>
              <div class="grid limits"><el-form-item :label="form.mode==='instant'?'总抽奖次数上限':'报名人数上限'"><el-input-number v-model="form.maxEntries" :min="1" :max="10000"/></el-form-item><template v-if="form.mode==='instant'"><el-form-item label="每人每日次数"><el-input-number v-model="form.dailyLimit" :min="1" :max="20"/></el-form-item><el-form-item label="每人活动总次数"><el-input-number v-model="form.totalLimit" :min="1" :max="100"/></el-form-item></template></div>
              <el-form-item label="参与条件"><el-checkbox v-model="form.requireStudent">需要学生认证</el-checkbox><el-checkbox v-model="form.memberOnly">仅有效会员</el-checkbox></el-form-item>
              <div class="section-head"><h3>奖品设置</h3><el-button v-if="editable" :disabled="form.prizes.length>=12" @click="addPrize">＋ 添加奖品</el-button></div>
              <div v-for="(prize,i) in form.prizes" :key="i" class="prize-editor">
                <div class="section-head"><b>奖项 {{i+1}}</b><el-button v-if="editable" link type="danger" :disabled="form.prizes.length===1" @click="form.prizes.splice(i,1)">移除</el-button></div>
                <div class="grid"><el-form-item label="奖品名称"><el-input v-model="prize.name" maxlength="80"/></el-form-item><el-form-item label="奖品类型"><el-select v-model="prize.kind"><el-option label="实物 · 凭码自提" value="physical"/><el-option label="优惠券 · 自动发放" value="coupon"/></el-select></el-form-item><el-form-item label="随机奖品份数"><el-input-number v-model="prize.quantity" :min="1" :max="1000"/></el-form-item><el-form-item v-if="form.mode==='instant'" label="单次中奖概率（%）"><el-input-number v-model="prize.percent" :min="0.01" :max="100" :precision="2" :step="1"/></el-form-item></div>
                <el-form-item v-if="prize.kind==='coupon'" label="关联优惠券"><el-select v-model="prize.couponId" filterable placeholder="选择库存和有效期充足的优惠券"><el-option v-for="c in options.coupons" :key="c.id" :value="c.id" :label="`${c.name} · 可用 ${Math.max(0,c.totalCount-c.receivedCount)} · 至 ${time(c.endAt)}`"/></el-select></el-form-item>
                <el-form-item label="奖品图片"><ImageUploadBox v-if="editable" v-model="prize.image" shape="square" scene="activity" :max-size="2"/><img v-else-if="prize.image" :src="prize.image" class="prize-preview"/><span v-else>使用默认礼物图标</span></el-form-item>
              </div>
              <el-alert v-if="form.mode==='instant'" :title="`总中奖概率 ${probability.toFixed(2)}%，未中奖概率 ${Math.max(0,100-probability).toFixed(2)}%。奖品耗尽后，该奖项概率按未中奖处理。`" :type="probability>100?'error':'info'" :closable="false"/>
              <p class="hint">优惠券在发布时预留库存，中奖后自动到账。奖品券独立于普通领券次数限制；实物由运营备货。首版免费参与。</p>
              <div class="grid"><el-form-item label="实物自提地点"><el-input v-model="form.pickupLocation" maxlength="200" placeholder="例如：大学生活动中心 101 室"/></el-form-item><el-form-item label="领取联系方式"><el-input v-model="form.contact" maxlength="100"/></el-form-item></div>
              <el-form-item label="活动说明（会展示给参与用户）"><el-input v-model="form.description" type="textarea" :rows="5" maxlength="5000" show-word-limit placeholder="说明奖品、领取时间与参与须知；平台会自动补充次数、开奖方式等规则。"/></el-form-item>
            </el-form>
          </el-tab-pane>
          <el-tab-pane v-if="canGift && form.mode==='scheduled' && form.id" label="指定赠送 · 超级管理员" name="gifts">
            <el-alert title="指定赠送会对用户公开说明，额外增加名额，不占随机奖品份数；名单用户不重复参与随机抽奖。" type="warning" :closable="false"/>
            <p class="hint">先保存活动和奖品，再设置名单。发布后锁定；如需改草稿奖品，请先清空并保存此名单。</p>
            <div v-for="(g,i) in gifts" :key="i" class="gift-row"><el-select v-model="g.userId" filterable remote :remote-method="searchUsers" placeholder="搜索昵称 / 用户 UID" :disabled="!editable"><el-option v-for="u in userOptions" :key="u.id" :value="u.id" :label="`${u.nickname || '同学'} · ${u.uid || u.id}`"/><el-option v-if="g.userId&&!userOptions.some(u=>u.id===g.userId)" :value="g.userId" :label="g.userId"/></el-select><el-select v-model="g.prizeId" placeholder="选择奖品" :disabled="!editable"><el-option v-for="p in form.prizes" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-input v-model="g.reason" placeholder="内部赠送原因（必填）" maxlength="200" :disabled="!editable"/><el-button v-if="editable" link type="danger" @click="gifts.splice(i,1)">删除</el-button></div>
            <div class="actions"><el-button v-if="editable" :disabled="gifts.length>=50" @click="gifts.push({userId:'',prizeId:'',reason:''})">＋ 添加用户</el-button><el-button v-if="editable" type="primary" :loading="saving" @click="saveGifts">保存赠送名单</el-button></div>
          </el-tab-pane>
          <el-tab-pane v-if="form.id" label="参与与领奖" name="entries"><div class="filters"><el-select v-model="outcome" clearable placeholder="全部结果" @change="entryPage=1;loadEntries()"><el-option v-for="(v,k) in outcomes" :key="k" :value="k" :label="v"/></el-select><el-button @click="loadEntries">刷新</el-button></div><el-table :data="entries" v-loading="recordsLoading"><el-table-column prop="nickname" label="用户" min-width="120"/><el-table-column label="来源" width="110"><template #default="{row}">{{row.source==='gift'?'指定赠送':'随机抽奖'}}</template></el-table-column><el-table-column label="结果" width="100"><template #default="{row}">{{outcomes[row.outcome]}}</template></el-table-column><el-table-column prop="prize.name" label="奖品" min-width="150"/><el-table-column label="领取状态" width="110"><template #default="{row}">{{claims[row.claimStatus]}}</template></el-table-column><el-table-column prop="deliveryError" label="发放异常" min-width="190"/><el-table-column label="参与时间" width="180"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column></el-table><el-pagination v-model:current-page="entryPage" :page-size="20" :total="entryTotal" layout="total, prev, pager, next" @current-change="loadEntries"/></el-tab-pane>
          <el-tab-pane v-if="form.id" label="开奖与操作记录" name="logs"><el-descriptions v-if="form.draw" :column="2" border><el-descriptions-item label="符合资格人数">{{form.draw.candidateCount}}</el-descriptions-item><el-descriptions-item label="完成时间">{{time(form.draw.createdAt)}}</el-descriptions-item><el-descriptions-item label="随机中奖人数">{{form.draw.randomWinners}}</el-descriptions-item><el-descriptions-item label="指定赠送人数">{{form.draw.giftedCount}}</el-descriptions-item></el-descriptions><el-empty v-else description="尚未执行统一开奖"/><el-table :data="logs"><el-table-column label="操作"><template #default="{row}">{{logLabels[row.action] || row.action}}</template></el-table-column><el-table-column prop="accountId" label="管理员编号"/><el-table-column label="时间"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column></el-table></el-tab-pane>
        </el-tabs>
      </div>
      <template #footer><div class="drawer-footer"><el-button @click="drawer=false">关闭</el-button><template v-if="canEdit && tab==='config'"><el-button v-if="editable && !hasSavedGifts" type="primary" :loading="saving" @click="save">保存草稿</el-button><el-button v-if="form.id && form.status==='draft'" type="success" :loading="saving" @click="publish">保存并发布</el-button><el-button v-if="form.status==='published'" :loading="saving" @click="act('pause')">暂停参与</el-button><el-button v-if="form.status==='paused'" :loading="saving" @click="act('resume')">恢复参与</el-button><el-button v-if="['published','paused'].includes(form.status)" type="danger" plain :loading="saving" @click="act(form.mode==='instant'?'finish':'cancel')">{{form.mode==='instant'?'结束活动':'取消活动'}}</el-button></template></div></template>
    </el-drawer>
    <el-dialog v-model="redeemOpen" title="实物奖品核销" width="480px"><p>核对用户出示的领取码，确认奖品已准备好后再核销。</p><el-input v-model="redeemCode" maxlength="24" placeholder="输入 24 位领取码"/><template #footer><el-button @click="redeemOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="redeem">确认核销</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { request } from '@/api/request'
import ImageUploadBox from '@/components/common/ImageUploadBox.vue'
import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore()
const canEdit=computed(()=>canGift.value || auth.permissions.includes('activity:edit') || auth.permissions.includes('*'))
const canGift=ref(false), options=ref<any>({regions:[],coupons:[],canGlobal:false})
const rows=ref<any[]>([]), total=ref(0), page=ref(1), keyword=ref(''), status=ref(''), loading=ref(false), error=ref('')
const drawer=ref(false), tab=ref('config'), form=ref<any>({prizes:[]}), saving=ref(false), detailLoading=ref(false)
const gifts=ref<any[]>([]), userOptions=ref<any[]>([]), entries=ref<any[]>([]), logs=ref<any[]>([]), outcome=ref(''), entryPage=ref(1), entryTotal=ref(0), recordsLoading=ref(false)
const redeemOpen=ref(false), redeemCode=ref('')
const statuses:Record<string,string>={draft:'草稿',published:'已发布',paused:'已暂停',finished:'已结束',cancelled:'已取消'}
const outcomes:Record<string,string>={waiting:'等待开奖',won:'已中奖',lost:'未中奖',excluded:'资格失效',cancelled:'活动取消'}
const claims:Record<string,string>={none:'—',pending:'待发放 / 领取',delivered:'券已到账',redeemed:'已核销'}
const logLabels:Record<string,string>={WELFARE_SAVE:'保存活动',WELFARE_GIFTS:'更新指定赠送',WELFARE_REDEEM:'核销实物',WELFARE_PUBLISH:'发布',WELFARE_PAUSE:'暂停',WELFARE_RESUME:'恢复',WELFARE_CANCEL:'取消',WELFARE_FINISH:'结束'}
const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone
const editable=computed(()=>canEdit.value && !form.value.publishedAt && (!form.value.id || form.value.status==='draft'))
const hasSavedGifts=computed(()=>Number(form.value.giftCount||0)>0 || (form.value.gifts||[]).length>0)
const probability=computed(()=>form.value.prizes.reduce((n:number,p:any)=>n+Number(p.percent||0),0))
const base='/admin/welfare'
const get=(path:string,params?:any)=>request.get<any,any>(base+path,{params})
const post=(path:string,data?:any)=>request.post<any,any>(base+path,data,{timeout:60000})
const time=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
const message=(e:any)=>e?.response?.data?.message || e?.message || '操作失败，请重试'
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const r=await get('/campaigns',{page:page.value,keyword:keyword.value,status:status.value});rows.value=r.list;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function search(){page.value=1;load()}
function addPrize(){form.value.prizes.push({name:'',kind:'physical',image:'',quantity:1,percent:1,couponId:''})}
function create(){const now=Date.now();form.value={title:'',description:'',cover:'',mode:'instant',status:'draft',regionId:options.value.canGlobal?'':options.value.regions[0]?.id||'',requireStudent:false,memberOnly:false,startAt:new Date(now+3600000).toISOString(),endAt:new Date(now+86400000).toISOString(),drawAt:new Date(now+86400000).toISOString(),claimUntil:new Date(now+8*86400000).toISOString(),dailyLimit:1,totalLimit:5,maxEntries:1000,pickupLocation:'',contact:'',prizes:[]};addPrize();gifts.value=[];tab.value='config';drawer.value=true}
function assign(row:any){userOptions.value=row.giftUsers||[];form.value={...row,regionId:row.regionId||'',prizes:row.prizes.map((p:any)=>({...p,percent:p.probabilityBps/100}))};gifts.value=(row.gifts||[]).map((g:any)=>({...g}))}
async function open(id:string,which:string){drawer.value=true;detailLoading.value=true;tab.value=which;entryPage.value=1;outcome.value='';try{assign(await get('/campaigns/'+id));await tabChanged()}catch(e){ElMessage.error(message(e));drawer.value=false}finally{detailLoading.value=false}}
async function persist(){const payload={...form.value,prizes:form.value.prizes.map((p:any)=>({...p,probabilityBps:Math.round(Number(p.percent)*100)}))};const row=form.value.id?await request.put<any,any>(base+'/campaigns/'+form.value.id,payload):await post('/campaigns',payload);assign(row);return row}
async function save(){if(saving.value)return;saving.value=true;try{await persist();ElMessage.success('草稿已保存');await load()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function publish(){if(saving.value)return;if(JSON.stringify(gifts.value.map(({userId,prizeId,reason})=>({userId,prizeId,reason})))!==JSON.stringify((form.value.gifts||[]).map(({userId,prizeId,reason}:any)=>({userId,prizeId,reason})))){ElMessage.warning('请先保存指定赠送名单');tab.value='gifts';return;}try{await ElMessageBox.confirm('发布后活动规则和赠送名单将锁定，并预留全部奖品券库存。确认发布？','发布抽奖',{type:'warning'})}catch{return}saving.value=true;try{if(!hasSavedGifts.value)await persist();await post('/campaigns/'+form.value.id+'/publish');assign(await get('/campaigns/'+form.value.id));ElMessage.success('活动已发布');await load()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function act(action:string){if(saving.value)return;const tips:Record<string,string>={pause:'暂停后不再接受新增参与，定时活动仍按原计划开奖。',resume:'恢复后，符合条件的用户可继续参与。',cancel:'取消后不会开奖，所有报名记录标记为已取消。报名截止后不能取消。',finish:'结束后不再接受抽奖，已获得的奖品仍可领取。'};try{await ElMessageBox.confirm(tips[action],'确认操作',{type:'warning'})}catch{return}saving.value=true;try{await post('/campaigns/'+form.value.id+'/'+action);assign(await get('/campaigns/'+form.value.id));await load()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
let userSearch=0
async function searchUsers(keyword:string){const current=++userSearch;if(keyword.trim().length<2){userOptions.value=[];return}try{const r=await get('/users',{keyword});if(current===userSearch)userOptions.value=r.list}catch{}}
async function saveGifts(){if(saving.value)return;saving.value=true;try{await request.put(base+'/campaigns/'+form.value.id+'/gifts',{gifts:gifts.value.map(({userId,prizeId,reason})=>({userId,prizeId,reason}))});assign(await get('/campaigns/'+form.value.id));ElMessage.success('赠送名单已保存');await load()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function loadEntries(){if(!form.value.id)return;recordsLoading.value=true;try{const r=await get('/campaigns/'+form.value.id+'/entries',{page:entryPage.value,outcome:outcome.value});entries.value=r.list;entryTotal.value=r.total}catch(e){ElMessage.error(message(e))}finally{recordsLoading.value=false}}
async function tabChanged(){if(!form.value.id)return;if(tab.value==='entries')await loadEntries();if(tab.value==='logs'){try{logs.value=(await get('/campaigns/'+form.value.id+'/logs')).list}catch(e){ElMessage.error(message(e))}}}
async function redeem(){if(saving.value)return;if(!/^[a-f0-9]{24}$/i.test(redeemCode.value.trim())){ElMessage.warning('请输入完整的 24 位领取码');return}saving.value=true;try{await post('/redeem',{code:redeemCode.value.trim()});ElMessage.success('核销成功，请交付奖品');redeemCode.value='';redeemOpen.value=false;if(tab.value==='entries')await loadEntries()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
onMounted(async()=>{await Promise.allSettled([load(),get('/capabilities').then(r=>canGift.value=r.canGift),get('/options').then(r=>options.value=r)])})
</script>
